let mounted = false;

function ensureSprite() {
  if (mounted || typeof document === "undefined") return;
  const holder = document.createElement("div");
  holder.setAttribute("aria-hidden", "true");
  holder.style.cssText = "position:absolute;width:0;height:0;overflow:hidden";
  holder.innerHTML = SPRITE;
  document.body.append(holder);
  mounted = true;
}

function basename(path: string) {
  const normalized = path.replace(/\\/g, "/");
  const parts = normalized.split("/").filter(Boolean);
  return parts[parts.length - 1] ?? "";
}

function openVariant(name: string) {
  return name.endsWith("Open") ? name : `${name}Open`;
}

/** Picks the reference's icon for a path, using whole names before suffixes. */
function chooseFileIcon(path: string, type: "file" | "directory" = "file", expanded = false) {
  const base = basename(path).toLowerCase();
  if (type === "directory") {
    for (const candidate of [base, `.${base}`, `_${base}`, `__${base}__`]) {
      const icon = FOLDER_NAMES[candidate];
      if (icon) return expanded ? openVariant(icon) : icon;
    }
    return expanded ? "FolderOpen" : "Folder";
  }
  const byName = FILE_NAMES[base];
  if (byName) return byName;
  const suffixes: string[] = [];
  for (let i = 0; i < base.length; i++) if (base[i] === ".") suffixes.push(base.slice(i + 1));
  for (const suffix of suffixes.sort((a, b) => b.length - a.length)) {
    const icon = FILE_EXTENSIONS[suffix];
    if (icon) return icon;
  }
  return "Document";
}

export function FileTypeIcon(props: JSX.SvgSVGAttributes<SVGSVGElement> & {
  path: string;
  type?: "file" | "directory";
  expanded?: boolean;
}) {
  ensureSprite();
  const [local, rest] = splitProps(props, ["path", "type", "expanded", "class"]);
  const name = createMemo(() => chooseFileIcon(local.path, local.type ?? "file", local.expanded ?? false));
  return (
    <svg
      {...rest}
      class={cn("size-4 shrink-0", local.class)}
      viewBox="0 0 16 16"
      aria-hidden="true"
    >
      <use href={`#lz-file-icon-${name()}`} />
    </svg>
  );
}
